-- Insert Quiz Questions for Lesson: Connect and Test the Review Destination

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 15 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 15 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'connect-test-review-destination' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson connect-test-review-destination not found in module 15';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should the review link be opened in a private browser window?', 
    '["It tests the customer''s direct experience without relying on an active signed-in session.","It makes the page load faster.","It hides the test from analytics.","It is required by LeadProspectrr."]'::jsonb,
    'It tests the customer''s direct experience without relying on an active signed-in session.',
    'A private browser window tests the customer''s direct experience without relying on cached sessions or saved passwords, giving an accurate view of what they will see.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you check after the link opens?', 
    '["The correct business name, location, and review destination.","The number of existing reviews.","The page loading speed.","The browser version."]'::jsonb,
    'The correct business name, location, and review destination.',
    'After the link opens, verify the correct business name, location, and review destination to ensure customers will leave reviews on the right page.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Should review requests be sent when the link points to the wrong location?', 
    '["No","Yes, the customer will find the right page.","Only if the business name is correct.","Yes, but only for test contacts."]'::jsonb,
    'No',
    'Never send review requests when the link points to the wrong location. This is the most damaging simple setup error and will result in lost reviews or reviews on the wrong business.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
